#!/usr/bin/env bash\nset -euo pipefail\n# Broad MARS oral artifact recovery; not a lip-seam-only runner.\nROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"\nBLENDER="${TRIPPEDD_BLENDER_BIN:-$ROOT/vendor/blender/blender}"\nTARGET="${1:-$ROOT/assets/rigs/MARS_FACE.blend}"\nFRAME="${2:-$ROOT/renders/_rig_measure/mouth_anatomy.json}"\nOUT="${3:-$ROOT/assets/variants/MARS_FACE_ORAL_SKIN_RECOVERY_REVIEW.blend}"\nEVID="${4:-$ROOT/.artifacts/god-molecule/mars-oral-artifact-recovery}"\nmkdir -p "$EVID"\n"$BLENDER" -b "$TARGET" --python "$ROOT/tools/character/repair_mars_oral_skin_artifacts.py" -- \\n  --target "$TARGET" --mouth-frame "$FRAME" --out "$OUT"\n"$BLENDER" -b "$OUT" --python "$ROOT/tools/character/mouth_truth.py" -- \\n  --rig "$OUT" --out "$EVID/mouth_truth" --seq\n"$BLENDER" -b "$OUT" --python "$ROOT/tools/character/survey_oral_aperture.py" -- \\n  --mouth-frame "$FRAME" --output "$EVID/aperture_survey.json"\necho "ORAL_ARTIFACT_RECOVERY: REVIEW_ONLY"\necho "REVIEW_BLEND=$OUT"\necho "EVIDENCE=$EVID"\n